#!/usr/bin/env python3
"""Writes the prompt of one volume (or all) for its English review PDF: docs/prompts/pdf/VOLn.md.

  python3 publish/pdf_prompt.py N [N …]      write the prompts named
  python3 publish/pdf_prompt.py all          Vols 1–30

Each file = a short block of facts about the volume and the questions it must ask (made from publish/pdf_prep_report.py at the time of writing;
the session re-reads the script, which wins) + the generic procedure docs/prompts/VOLN_PDF_PREP_PROMPT.md with N filled in.  The single source of
the procedure stays the generic file; never edit a generated prompt by hand, change the generic file or this script and run it again."""
import sys, re, pathlib, json
PUB = pathlib.Path(__file__).resolve().parent; ROOT = PUB.parent
sys.path.insert(0, str(PUB)); import pdf_prep_report as R
GEN = ROOT / 'docs' / 'prompts' / 'VOLN_PDF_PREP_PROMPT.md'; OUT = ROOT / 'docs' / 'prompts' / 'pdf'
def asks(n, f):
    a = []
    if 'lines' not in f: return ['The English file is missing: stop and tell the user.']
    if 'UNFINISHED' in f['progress'] or 'NOT READY' in f['verdict']: a.append('The translation is not finished: stop and tell the user.')
    elif not re.search('final', f['progress']) and f['progress'] != 'closed file':
        a.append(f"The English file's progress note ({f['progress']}) does not say final: read `vol{n}/STATUS.md`; if the volume is not complete, **stop and ask** before building.")
    if not f['pubcfg']: a.append(f"No `vol{n}/pubcfg.json`: write the minimal one (Step 1) from `STATUS.md`/`volcfg.json`; any of range, Aṣṭaka/Adhyāya line, imprint, press, year you cannot find there prints as \"[… to be supplied]\": list them as questions, do not invent.")
    fe = ROOT / f'vol{n}' / 'frontmatter_en.json'
    if fe.exists() and json.loads(fe.read_text(encoding='utf8')).get('preface'): f['preface'] = True
    if not f['preface']: a.append('No preface of the original in the English file or in `frontmatter_en.json`: print none (page 8 is skipped), **ask the user** whether it should be translated (give the estimate, Step 3b.2).')
    if not (f['contents'] or f['contents_en_json']): a.append('No contents in English for this volume: **ask the user** (Step 3b.3: no contents page, or a table of Sūktas from the headings; the number of Sūktas is in the report). Do not make one by agents or API.')
    if f['family'] == 'A' and n in (9, 10): a.append("`clean9` (`publish/vol67_clean.py`) discards everything before the first Sūkta, preface and contents with it: repair in the shared cleaner (Step 3b.2) and ask if unsure what belongs to the preface.")
    if n in (1, 5): a.append('This volume has an Introduction (Pūrva-pīṭhikā, long Part I): `mark_slots` leaves the `introduction` slot unmarked on purpose. **Ask the user** where the Introduction ends and which part is the body of page 11 before marking it.')
    if f['family'] == 'A' and n not in (1, 2): a.append('Old builder: it prints its own generated contents list and no list of abbreviations; Step 3b.3 (iii) and 3b.4 apply.')
    if json.loads((ROOT / f'vol{n}' / 'frontmatter_en.json').read_text(encoding='utf8')).get('board') if (ROOT / f'vol{n}' / 'frontmatter_en.json').exists() else False: a.append('Has a board of scholars section (`frontmatter_en.json`): **no page of its own**, it will be merged into the thank-you page later; the embedder removes it. Just list it in the hand-over.')
    if f['done']: a.append('Prepared already: only re-build with the embedder, check, and look at pages 1–30.')
    return a
def make(n):
    f = R.facts(n, True); f['pubcfg'] = f.get('pubcfg', (ROOT / f'vol{n}' / 'pubcfg.json').exists())
    fam = f.get('family', '?')
    head = [f'# Volume {n}: English review PDF — prompt (generated by `publish/pdf_prompt.py`, do not edit by hand)', '',
            f'Branch to work on: `claude/vol{n}-pdf` (create it from `main` if it does not exist; never push to `main`).', '',
            '## Facts of this volume when the prompt was written (the script `publish/pdf_prep_report.py` is always right)']
    if 'lines' in f:
        head += [f"- family {fam}; builder: {f['builder']}; layout {f['layout']}; {f['sukta']} Sūkta headings, {f['rik']} Ṛk headings; English file {f['lines']} lines, progress: {f['progress']}",
                 f"- `[?]` {f['q']}, `[sic]` {f['sic']}, `**NOTE**` {f['note']}, `**GLOSS**` {f['gloss']}, Kannada-script lines {f['kn_script']}, lines ending in dots {f['dots']}, clean-up dry run {f['cleanup_total']}",
                 f"- preface of the original: {'yes' if f['preface'] else 'no'}; contents: {'yes (English file)' if f['contents'] else ('contents_en.json' if f['contents_en_json'] else 'no')}; introduction: {'yes' if f['intro'] else 'no'}; pubcfg.json: {'yes' if f['pubcfg'] else 'no'}"]
    head += ['', '## Page order (user, Nov 28 2026; the embedder is ON and builds pages 1–7 itself)',
             '1 title · 2 imprint · 3 king · 4 guru · 5 present day · 6 thank-you · 7 our preface (placeholder) · 8 preface of the original ("Preface", Pīṭhike in footer) · 9 contents · 10 list of abbreviations · 11 Introduction (Vols 1, 5 only) · text, arabic 1 · closing remarks (off).', '',
             '## Where this volume needs a decision or a question to the user (ask; never guess)']
    head += [f'- {x}' for x in asks(n, f)] or ['- none known; ask whenever something does not fit the procedure.']
    head += ['', '**Rule for the whole task: if something is amiss, missing or contradicts the order above, stop that step, write the question down with the page or file, and ask the user at the hand-over (or at once if the rest depends on it). Do not decide for the user, do not invent text.**', '', '---', '']
    body = GEN.read_text(encoding='utf8').replace('Volume N', f'Volume {n}').replace('volN', f'vol{n}').replace('`N`', f'`{n}`').replace('build_all.py N', f'build_all.py {n}').replace('pdf_prep_report.py N', f'pdf_prep_report.py {n}').replace('cleanup_remarks.py N', f'cleanup_remarks.py {n}').replace('pdf_check.py N', f'pdf_check.py {n}').replace('join_pages.py prep N', f'join_pages.py prep {n}')
    body = body.split('\n', 1)[1]          # the generic title line
    OUT.mkdir(parents=True, exist_ok=True); (OUT / f'VOL{n}.md').write_text('\n'.join(head) + body, encoding='utf8')
if __name__ == '__main__':
    a = sys.argv[1:] or ['all']; vols = range(1, 31) if a == ['all'] else [int(x) for x in a]
    for n in vols: make(n)
    print('written:', len(list(vols)), 'prompts in', OUT.relative_to(ROOT))
